        check_newval = (newval < -2 ** 31 or newval >= 2 ** 31)
        if check_newval and config.enforce_valid_values:
            dcm_limit = "-2**31 to (2**31 - 1) for IS"
            message = "Value exceeds DICOM limits of %s" % (dcm_limit)
            raise OverflowError(message)
        return newval

